# Let me analyze bounding boxes of each object
objects = {
    0: [(1, 9), (2, 7), (2, 8), (2, 9), (3, 7), (3, 8), (3, 9)],
    2: [(6, 12), (6, 13), (6, 14), (6, 15), (6, 16), (7, 12), (8, 12), (9, 12), (10, 12)],
    3: [(1, 13), (1, 14), (2, 14), (9, 6), (10, 6)],
    4: [(10, 0)],
    8: [(5, 2), (5, 3), (6, 2), (6, 3), (6, 10), (7, 2), (7, 3), (7, 10), 
        (8, 2), (8, 3), (8, 10), (8, 16), (9, 14), (9, 15), (9, 16), 
        (10, 14), (10, 15), (10, 16)]
}

def bounding_box(pixels):
    if not pixels:
        return None
    rows = [p[0] for p in pixels]
    cols = [p[1] for p in pixels]
    return (min(rows), max(rows) + 1, min(cols), max(cols))

for val, pixels in objects.items():
    print(f"\nObject {val} (count: {len(pixels)}):")
    bbox = bounding_box(pixels)
    if bbox:
        print(f"  BBox: rows {bbox[0]}-{bbox[1]-1}, cols {bbox[2]}-{bbox[3]}")
        print(f"  Size: {bbox[1] - bbox[0]} x {bbox[3] - bbox[2]}")

# Maybe the answer is to extract each object's bounding box?
# Let's see if there's a pattern with dimensions

print("\n\nExtracting bounding boxes as separate grids:")
for val, pixels in objects.items():
    if pixels:
        rmin, rmax, cmin, cmax = bounding_box(pixels)
        rsize = rmax - rmin
        csize = cmax - cmin

        obj_grid = [[7] * csize for _ in range(rsize)]
        for r, c in pixels:
            obj_grid[r - rmin][c - cmin] = val

        print(f"\nObject {val} extracted ({rsize}x{csize}):")
        for row in obj_grid:
            print(row)

